import type { Entity } from "./taxonomy";

/**
 * The third part of the clinical index — the September 2026 expansion.
 *
 * Written after the first thousand pages were live and measured against a
 * second keyword harvest seeded with conditions, drugs, labs and skills rather
 * than exam terms. That harvest showed two things the first index could not:
 * which subjects people search in the "nursing interventions / nursing
 * diagnosis / nursing care plan" phrasing, and which clinical subjects the
 * library skipped because the first pass was written by body system and ran
 * out of room before it ran out of subject.
 *
 * Same rule as the other two files: one real thing a nurse must know, one
 * specific hook the writer can build the page around. Where a subject here
 * sits close to an existing entry, it is because the exam treats them
 * differently — the planner's similarity guard will fold any that are not.
 *
 * Topic keys must exist in the core index.
 */
